// Orchestrator tracker-read ops for /wf:fleet WF-405, recorded per the fake
// scripted-response protocol (tracker.ops.md steps 3-5). Deterministic: responses
// are resolved straight from scripts.json so the op-log matches the scenario exactly.
const fs = require('fs');
const root = '/tmp/tmp.DMvrxuCJhS/workspace/_local';
const scripts = JSON.parse(fs.readFileSync(root + '/fake/scripts.json', 'utf8'));
const logPath = root + '/fake/op-log.jsonl';

let lines = [];
try { lines = fs.readFileSync(logPath, 'utf8').split('\n').filter(Boolean); } catch (e) {}

const countOp = (surface, op) =>
  lines.filter(l => { const o = JSON.parse(l); return o.surface === surface && o.op === op; }).length;

// [surface, op, args, sequenceMode]
// sequenceMode=true  -> scripted array is an ordered response-sequence (element at call-index)
// sequenceMode=false -> scripted value (incl. a list) is the whole response
const ops = [
  ['tracker', 'list_children', { 'parent-id': 'WF-405' }, false],
  ['tracker', 'get',           { id: 'WF-406' },          true ], // get call-index 0 -> WF-406
  ['tracker', 'list_blockers', { id: 'WF-406' },          false],
  ['tracker', 'get',           { id: 'WF-409' },          true ], // get call-index 1 -> WF-409
  ['tracker', 'list_blockers', { id: 'WF-409' },          false],
];

for (const [surface, op, args, seqMode] of ops) {
  const seq = lines.length + 1;
  const callIndex = countOp(surface, op);
  const scripted = scripts[surface][op];
  const response = (seqMode && Array.isArray(scripted))
    ? (callIndex < scripted.length ? scripted[callIndex] : scripted[scripted.length - 1])
    : scripted;
  lines.push(JSON.stringify({ seq, surface, op, args, response }));
}

fs.writeFileSync(logPath, lines.join('\n') + '\n');
console.log('op-log now has', lines.length, 'lines');

