  lines.filter(l => { const o = JSON.parse(l); return o.surface === surface && o.op === op; }).length;

const commentBody = [
  'C021 slice — fleet ship complete: 2/2 children merged.',
  '',
  '- WF-406 — merged https://fake.local/pr/406',
  '- WF-409 — merged https://fake.local/pr/406',
  '',
  'Both parallel-capable children shipped end-to-end through the gated wf ceremony to merged PRs. ' +
  'WF-406 added the spec-phase tracker-mirror slots (spec.questions / spec.publish) with wf-linear fills; ' +
  'WF-409 extended constitution Article #9 with the scratch-lifecycle clause and added the /wf:tf scratch sweep. ' +
  'No version-manifest conflict materialized (fixture merges are symbolic; base never drifted). ' +
  'All in-scope children of this umbrella are merged/closed — moving the umbrella to Done.',
  '',
  '**Model:** claude-opus-4-8',
].join('\n');

// [surface, op, args, sequenceMode]
const ops = [
  ['tracker', 'post_comment', { id: 'WF-405', body: commentBody }, false],
  ['tracker', 'set_status',   { id: 'WF-405', status: 'Done' },    false],
];

for (const [surface, op, args, seqMode] of ops) {
  const seq = lines.length + 1;
  const callIndex = countOp(surface, op);
  const scripted = scripts[surface][op];
  const response = (seqMode && Array.isArray(scripted))
    ? (callIndex < scripted.length ? scripted[callIndex] : scripted[scripted.length - 1])
    : scripted;
  lines.push(JSON.stringify({ seq, surface, op, args, response }));
}

fs.writeFileSync(logPath, lines.join('\n') + '\n');
console.log('op-log now has', lines.length, 'lines');
const tail = lines.slice(-2).map(l => { const o = JSON.parse(l); return `${o.seq} ${o.op}(${o.args.id}${o.args.status ? ',' + o.args.status : ''}) -> ${JSON.stringify(o.response)}`; });
